<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">                     &quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">build_scorer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;: 1_500_000_000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  // 评分器构建耗时 71%</span></span>
